EQUIVALENCIAS = {  # enmienda 4, RF-CAT-44: tipo viejo → (se_vende, se_compra, se_fabrica)
    "INSUMO": (False, True, False),
    "ENVASE": (False, True, False),
    "MERCADERIA": (True, True, False),
    "GRANEL": (False, False, True),
    "TERMINADO": (True, False, True),
}


def convertir(apps, schema_editor):
    """Tipos viejos → BIEN + casillas; presentación → receta (granel × contenido + materiales);
    el contenido de la presentación pasa al producto (ISC). Sin entradas de historial (PO)."""
    Producto = apps.get_model("catalog", "Producto")
    Presentacion = apps.get_model("catalog", "Presentacion")
    PresentacionMaterial = apps.get_model("catalog", "PresentacionMaterial")
    RecetaComponente = apps.get_model("catalog", "RecetaComponente")
    for viejo, (vende, compra, fabrica) in EQUIVALENCIAS.items():
        Producto.objects.filter(tipo=viejo).update(
            tipo="BIEN", se_vende=vende, se_compra=compra, se_fabrica=fabrica
        )
    Producto.objects.filter(vida_util_dias=0).update(vida_util_dias=None)  # ahora > 0 u opcional
    for p in Presentacion.objects.all():
        RecetaComponente.objects.create(
            producto_id=p.producto_id,
            componente_id=p.granel_id,
            cantidad_por_unidad=p.contenido_litros,
        )
        for m in PresentacionMaterial.objects.filter(presentacion=p):
            RecetaComponente.objects.create(
                producto_id=p.producto_id,
                componente_id=m.material_id,
                cantidad_por_unidad=m.cantidad_por_unidad,
            )
        Producto.objects.filter(pk=p.producto_id).update(contenido_litros=p.contenido_litros)
    # Las FK diferidas de los datos convertidos se verifican ya: si no, PostgreSQL no deja
    # alterar las tablas en la misma transacción ("pending trigger events").
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


